    "settings.typesafe.shadowSummary": "判断任务的难度、风险、意图以及若干事实。开启后，会把有把握的判断用于挑选适合任务的模型。",
    "settings.typesafe.recallSummary": "判断记忆检索找到的笔记与当前请求有多契合。开启后，先读最契合的笔记，并去掉无关的笔记。",
    "settings.typesafe.skillsSummary": "代理搜索技能时，为已安装的技能排序。影子模式记录排序，并返回按词匹配的结果。",
    "settings.typesafe.browserSummary": "选择网页上下一步要点的按钮或链接。开启后，停下的自动化和按目标运行的自动操作会按此选择点击。",
    "settings.typesafe.emulator": "手机自动操作",
    "settings.typesafe.emulatorSummary": "选择手机（iOS、Android）画面上下一步要点的控件。开启后，按目标运行的自动操作会按此选择点击。",
    "settings.typesafe.emulatorHint": "选择手机（iOS、Android）画面上下一步要点的一个控件。开启后按此选择点击，但只点击在画面上重新确认过的编号，并用你指定的确认文字检查结果。发送的是已编号控件的辅助功能文本、目标、平台和设备标识，发往 api.typesafe.ai。它与浏览器、桌面设置分开，只有你亲自开启此功能才会运行。",
    "settings.typesafe.cover": "露出被遮挡的点击目标",
    "settings.typesafe.coverSummary": "要点击的位置被其他窗口挡住时，判断是什么挡住了它、先做什么。开启后按判断把目标窗口移到最前或挪到空处，再次确认后点击。",
    "settings.typesafe.coverHint": "只有当按编号要点击的位置被其他窗口挡住时才会询问。发送的只有目标窗口及覆盖其上的窗口（最多 12 个）的应用名称、层级、大小和位置，以及被遮挡的比例；不发送窗口标题、屏幕文字或屏幕图像。只移动目标窗口本身（移到最前或挪开）；覆盖它的窗口不会被读取、关闭或移动。覆盖物看起来像系统通知、权限请求或等待回答的对话框，或判断不确定时，会停手并用一行询问你；1.5 秒内没有回答时，按不经判断时的做法继续。在「仅记录」和关闭时，不经判断直接把目标窗口移到最前，仍被挡住就挪开（若是其他应用的浮动窗口则询问你）。",
    "settings.typesafe.desktopSummary": "选择桌面应用中下一步要点的控件。开启后，按目标运行的自动操作会按此选择点击。",
    "settings.typesafe.stallSummary": "判断一个沉默下来的工作者为何停下。开启后会把原因告诉协调者；若是暂时的 API 错误，则让工作继续。",
    "settings.typesafe.placementSummary": "判断刚启动的工作者应放在标签页、分屏还是后台。开启后按此判断放置工作者。",
