    "settings.typesafe.standings": "各功能状态",
    "settings.typesafe.standingsAbout": "开启期间，显示每个功能是在实际应用判断，还是仍只记录。记录中功能旁的数字是下一次判定所需样本中已收集的数量。",
    "settings.typesafe.standingsAsking": "正在向 zo 询问各功能状态…",
