    "emulator.realPhone.consent": "代理请求从内部控制真机“{{phone}}”。允许后，将在此 Mac 上构建加了我们小补丁的 Appium WebDriverAgent {{tag}}（修改版），以团队“{{team}}”（{{kind}}）的签名安装到手机。Xcode 会在你的 Apple 账户中为此运行器创建 App ID 和描述文件。之后代理无需 Mac 指针即可读取屏幕、点按和输入，你正在使用手机时也可以；锁定手机即可让它停下。不会解锁手机或输入密码；支付和转账仍由你决定。对这台手机，在设置中关闭或运行 phone-remove 前一直有效。允许请点完成。",
    "emulator.realPhone.remove": "代理请求删除“{{phone}}”上的 WebDriverAgent 和此 Mac 上的构建，并关闭真机控制。手机上的其他内容不变。Xcode 在你的 Apple 账户中创建的 App ID 和描述文件会保留。允许请点完成。",
    "emulator.realPhone.androidConsent": "代理请求通过 USB 或无线调试（adb）控制 Android 真机“{{phone}}”。允许后，会把我们的小输入助手复制到手机的 /data/local/tmp，以便输入任何语言；不安装任何应用。之后代理无需 Mac 指针即可读取屏幕、点按、滑动和输入，你正在使用手机时也可以；锁定手机即可让它停下。不会解锁、按电源键、更改设置、安装或删除应用、输入密码；支付和转账仍由你决定。对这台手机，在设置中关闭或运行 phone-remove 前一直有效。允许请点完成。",
    "emulator.realPhone.androidRemove": "代理请求从 Android 真机“{{phone}}”删除输入助手并关闭对它的控制。手机上的其他内容不变。允许请点完成。",
    "emulator.realPhone.title": "真机控制",
    "emulator.realPhone.about": "代理通过手机内的修改版 WebDriverAgent 控制手机，不用 Mac 指针。只有你能在首次使用的卡片上逐台开启。你正在使用手机时代理也能点按；锁定手机即可让它停下。解锁、密码、支付和转账始终由你决定。构建时会在 Apple 账户中为此运行器创建 App ID 和描述文件。 Android 真机通过 USB 调试控制，无需构建：允许后会把一个小的输入助手放到 /data/local/tmp，代理不会碰电源键、设置或应用。",
    "emulator.realPhone.allowed": "已允许（关闭会结束运行器）",
